#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int INF = 1e9;

struct FlowEdge {
    int to, rev, flow, capacity;
    FlowEdge(int to, int rev, int flow, int capacity) : to(to), rev(rev), flow(flow), capacity(capacity) {}
};
vector<FlowEdge> graph[MAXN];

void connectVertices(int u, int v, int c, int rc = 0) {
    FlowEdge e1(v, graph[v].size(), 0, c);
    FlowEdge e2(u, graph[u].size(), 0, rc);
    graph[u].push_back(e1);
    graph[v].push_back(e2);
}

int distArr[MAXN], ptrArr[MAXN], sIdx, tIdx;

bool buildLevelGraph() {
    memset(distArr, -1, sizeof(distArr));
    distArr[sIdx] = 0;
    queue<int> q({sIdx});
    while (!q.empty() && distArr[tIdx] == -1) {
        int u = q.front(); q.pop();
        for (auto &edge : graph[u]) {
            int v = edge.to;
            if (distArr[v] == -1 && edge.flow < edge.capacity) {
                distArr[v] = distArr[u] + 1;
                q.push(v);
            }
        }
    }
    return distArr[tIdx] != -1;
}

int pushFlow(int u, int flow) {
    if (u == tIdx || flow == 0)
        return flow;
    for (int &i = ptrArr[u]; i < graph[u].size(); i++) {
        auto &e = graph[u][i];
        int v = e.to;
        if (distArr[v] != distArr[u] + 1)
            continue;
        if (int pushed = pushFlow(v, min(flow, e.capacity - e.flow))) {
            e.flow += pushed;
            graph[v][e.rev].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int computeMaxFlow() {
    int totalFlow = 0;
    while (buildLevelGraph()) {
        memset(ptrArr, 0, sizeof(ptrArr));
        while (int pushed = pushFlow(sIdx, INT_MAX))
            totalFlow += pushed;
    }
    return totalFlow;
}

int deltaX[] = {-1, 0, 0, 1};
int deltaY[] = {0, -1, 1, 0};

int n, m;
using Grid = vector<vector<int>>;
using Point = array<int, 2>;
Grid obs, distT, distD;

void runBFS(int r, int c, Grid &dis, bool check = false) {
    for (int i = 0; i < n; i++)
        fill(dis[i].begin(), dis[i].end(), -1);
    dis[r][c] = 0;
    queue<Point> q;
    q.push({r, c});
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        if (check && dis[p[0]][p[1]] == distT[p[0]][p[1]])
            continue;
        Point neighbor;
        for (int i = 0; i < 4; i++) {
            neighbor = {p[0] + deltaX[i], p[1] + deltaY[i]};
            if (neighbor[0] < 0 || neighbor[0] >= n || neighbor[1] < 0 || neighbor[1] >= n || dis[neighbor[0]][neighbor[1]] != -1 || obs[neighbor[0]][neighbor[1]])
                continue;
            if (check && distT[neighbor[0]][neighbor[1]] > -1 && dis[p[0]][p[1]] + 1 > distT[neighbor[0]][neighbor[1]])
                continue;
            dis[neighbor[0]][neighbor[1]] = dis[p[0]][p[1]] + 1;
            q.push(neighbor);
        }
    }
}

vector<string> lab, rea;

int main() {
    cin >> n >> m;
    lab.resize(n);
    rea.resize(n);
    for (auto &x : lab)
        cin >> x;
    for (auto &x : rea)
        cin >> x;
    obs.assign(n, vector<int>(n));
    distT.assign(n, vector<int>(n));
    distD.assign(n, vector<int>(n));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            obs[i][j] = (lab[i][j] == 'Y');
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (lab[i][j] == 'Z')
                runBFS(i, j, distT);
    sIdx = 2 * n * n + 5;
    tIdx = sIdx + 1;
    for (int x = 0; x < n; x++) {
        for (int y = 0; y < n; y++) {
            if (lab[x][y] == 'Z' || lab[x][y] == 'Y')
                continue;
            connectVertices(sIdx, n * x + y, lab[x][y] - '0');
            connectVertices(n * n + n * x + y, tIdx, rea[x][y] - '0');
            runBFS(x, y, distD, true);
            for (int xp = 0; xp < n; xp++) {
                for (int yp = 0; yp < n; yp++) {
                    if (distD[xp][yp] != -1 && distD[xp][yp] <= m) {
                        connectVertices(n * x + y, n * n + n * xp + yp, INF);
                    }
                }
            }
        }
    }
    cout << computeMaxFlow() << '\n';
}
